initJs:
function(container, apiUrl, tables) {
  let currentApplyId = null;
  let validationPassed = false;

  // モデル選択ドロップダウンの初期化
  function initModelSelect() {
    const modelSelect = container.querySelector('#select-model');
    // サンプルモデルデータ
    const models = [
      { id: 'model-001', name: 'AI需要予測モデル v2.1', version: '2.1.0', accuracy: '94.2%', created: '2024-01-15' },
      { id: 'model-002', name: 'AI需要予測モデル v2.0', version: '2.0.5', accuracy: '92.8%', created: '2024-01-10' },
      { id: 'model-003', name: 'AI需要予測モデル v1.9', version: '1.9.8', accuracy: '91.5%', created: '2024-01-05' }
    ];

    models.forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (精度: ${model.accuracy})`;
      option.dataset.model = JSON.stringify(model);
      modelSelect.appendChild(option);
    });
  }

  // 店舗一覧の初期化
  function initStoreList() {
    const storeList = container.querySelector('#store-list');
    const stores = tables[1]?.records || [
      { id: 'store-001', name: '本店', code: 'S001' },
      { id: 'store-002', name: '支店A', code: 'S002' },
      { id: 'store-003', name: '支店B', code: 'S003' }
    ];

    storeList.innerHTML = stores.map(store => `
      <label style="display: block; margin-bottom: 5px; color: var(--text);">
        <input type="checkbox" class="store-checkbox" value="${store.id}"> ${store.name} (${store.code})
      </label>
    `).join('');
  }

  // モデル詳細表示
  function showModelDetails(modelData) {
    const detailsDiv = container.querySelector('#model-details');
    if (modelData) {
      container.querySelector('#detail-model-name').textContent = modelData.name;
      container.querySelector('#detail-version').textContent = modelData.version;
      container.querySelector('#detail-accuracy').textContent = modelData.accuracy;
      container.querySelector('#detail-created').textContent = modelData.created;
      detailsDiv.style.display = 'block';
    } else {
      detailsDiv.style.display = 'none';
    }
  }

  // 影響範囲分析の更新
  function updateImpactAnalysis() {
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const impactDetails = container.querySelector('#impact-details');

    if (selectedModel && selectedStores.length > 0) {
      impactDetails.innerHTML = `
        <div style="color: var(--text);">
          <p><strong>対象店舗数:</strong> ${selectedStores.length}店舗</p>
          <p><strong>予想処理時間:</strong> 約${selectedStores.length * 2}分</p>
          <p><strong>影響システム:</strong> 需要予測システム、発注システム</p>
          <p><strong>ダウンタイム:</strong> なし（無停止切替）</p>
        </div>
      `;
    } else {
      impactDetails.textContent = 'モデルと店舗を選択してください';
      impactDetails.style.color = 'var(--text-muted)';
    }
  }

  // 検証実行
  function runValidation() {
    const validationStatus = container.querySelector('#validation-status');
    const validateBtn = container.querySelector('#btn-validate');

    validateBtn.disabled = true;
    validationStatus.innerHTML = '<span style="color: #ffa500;">検証実行中...</span>';

    setTimeout(() => {
      // ランダムで成功/失敗を決定（テスト用）
      const success = Math.random() > 0.2; // 80%の確率で成功

      if (success) {
        validationStatus.innerHTML = `
          <div style="color: #4caf50;">
            <strong>✓ 検証完了</strong>
            <ul style="margin: 10px 0; padding-left: 20px;">
              <li>データ品質チェック: OK</li>
              <li>精度閾値チェック: OK (94.2% > 90%)</li>
              <li>互換性チェック: OK</li>
            </ul>
          </div>
        `;
        validationPassed = true;
        updateApplyButtonState();
      } else {
        validationStatus.innerHTML = `
          <div style="color: #ff6b6b;">
            <strong>✗ 検証失敗</strong>
            <ul style="margin: 10px 0; padding-left: 20px;">
              <li>データ品質チェック: OK</li>
              <li>精度閾値チェック: NG (89.1% < 90%)</li>
              <li>互換性チェック: OK</li>
            </ul>
          </div>
        `;
        validationPassed = false;
        updateApplyButtonState();
      }

      validateBtn.disabled = false;
    }, 2000);
  }

  // 適用ボタンの状態更新
  function updateApplyButtonState() {
    const applyBtn = container.querySelector('#btn-apply');
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#start-datetime').value;

    applyBtn.disabled = !(selectedModel && selectedStores.length > 0 && startDateTime && validationPassed);
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // ログ追加
  function addLog(message) {
    const logContent = container.querySelector('#log-content');
    const timestamp = new Date().toLocaleString();
    logContent.innerHTML += `[${timestamp}] ${message}\n`;
    logContent.scrollTop = logContent.scrollHeight;
  }

  // 進捗更新
  function updateProgress(percent, message) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressSection = container.querySelector('#progress-section');

    progressSection.style.display = 'block';
    progressBar.style.width = `${percent}%`;
    progressText.textContent = `${percent}% - ${message}`;
  }

  // モデル適用実行
  function executeModelApply() {
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#start-datetime').value;

    // バリデーション
    if (!selectedModel) {
      showError('適用対象モデルを選択してください');
      return;
    }

    if (selectedStores.length === 0) {
      showError('適用対象店舗を選択してください');
      return;
    }

    if (!startDateTime) {
      showError('適用開始日時を入力してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      showError('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!validationPassed) {
      showError('適用前検証NGのため、モデル適用を実行できません');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    // 適用処理開始
    currentApplyId = 'apply-' + Date.now();
    const applyBtn = container.querySelector('#btn-apply');
    applyBtn.disabled = true;

    addLog('モデル適用処理を開始しました');
    updateProgress(0, '準備中');

    // 段階的な進捗シミュレーション
    const steps = [
      { percent: 10, message: 'モデル検証中', delay: 1000 },
      { percent: 30, message: 'バックアップ作成中', delay: 2000 },
      { percent: 50, message: 'モデルデプロイ中', delay: 2000 },
      { percent: 70, message: '店舗別設定適用中', delay: 3000 },
      { percent: 90, message: '本番切替中', delay: 1500 },
      { percent: 100, message: '適用完了', delay: 500 }
    ];

    let currentStep = 0;
    function processNextStep() {
      if (currentStep < steps.length) {
        const step = steps[currentStep];
        setTimeout(() => {
          updateProgress(step.percent, step.message);
          addLog(`${step.message}... (${step.percent}%)`);

          if (step.percent === 100) {
            addLog('モデル適用処理が正常に完了しました');
            container.querySelector('#btn-rollback').disabled = false;
            applyBtn.textContent = '適用完了';
          }

          currentStep++;
          processNextStep();
        }, step.delay);
      }
    }

    processNextStep();
  }

  // ロールバック実行
  function executeRollback() {
    if (!confirm('前のモデルにロールバックしますか？')) {
      return;
    }

    addLog('ロールバック処理を開始しました');
    updateProgress(0, 'ロールバック準備中');

    setTimeout(() => {
      updateProgress(50, 'ロールバック実行中');
      addLog('前バージョンのモデルに切り替え中...');
    }, 1000);

    setTimeout(() => {
      updateProgress(100, 'ロールバック完了');
      addLog('ロールバック処理が正常に完了しました');
      container.querySelector('#btn-rollback').disabled = true;
      container.querySelector('#btn-apply').textContent = 'モデル適用実行';
      container.querySelector('#btn-apply').disabled = false;
    }, 3000);
  }

  // イベントリスナー設定
  container.querySelector('#select-model').addEventListener('change', (e) => {
    const selectedOption = e.target.selectedOptions[0];
    if (selectedOption && selectedOption.dataset.model) {
      const modelData = JSON.parse(selectedOption.dataset.model);
      showModelDetails(modelData);
    } else {
      showModelDetails(null);
    }
    validationPassed = false;
    container.querySelector('#validation-status').textContent = '検証を実行してください';
    container.querySelector('#validation-status').style.color = 'var(--text-muted)';
    updateImpactAnalysis();
    updateApplyButtonState();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateImpactAnalysis();
    updateApplyButtonState();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateImpactAnalysis();
      updateApplyButtonState();
    }
  });

  container.querySelector('#start-datetime').addEventListener('change', updateApplyButtonState);

  container.querySelector('#btn-validate').addEventListener('click', runValidation);

  container.querySelector('#btn-apply').addEventListener('click', executeModelApply);

  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期化
  initModelSelect();
  initStoreList();

  // デフォルトの適用開始日時を現在時刻に設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#start-datetime').value = now.toISOString().slice(0, 16);
}
